mkdir -p src test && cat > package.json <<'EOF'
{
  "name": "unpipe-server",
  "version": "0.1.0",
  "private": true,
  "description": "Node.js HTTP server that can reliably unpipe a stream from all of its destinations",
  "type": "commonjs",
  "main": "src/server.js",
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "start": "node src/server.js",
    "test": "node --test"
  }
}
EOF
cat > src/unpipe.js <<'EOF'
'use strict'

/**
 * Detach a readable stream from every destination it is piped to.
 *
 * Modern streams: `unpipe()` with no argument removes all destinations.
 * Legacy (pre-streams2) streams have no `unpipe`, and `Stream#pipe` wires
 * a `close` listener named `cleanup` on the source; invoking those removes
 * the pipe's listeners.
 */
function unpipe (stream) {
  if (!stream) {
    throw new TypeError('argument stream is required')
  }

  if (typeof stream.unpipe === 'function') {
    stream.unpipe()
    return
  }

  if (!hasPipeDataListeners(stream)) {
    return
  }

  for (const listener of stream.listeners('close')) {
    if (listener.name === 'cleanup' || listener.name === 'onclose') {
      listener.call(stream)
    }
  }
}

function hasPipeDataListeners (stream) {
  return stream.listeners('data').some((l) => l.name === 'ondata')
}

module.exports = unpipe
EOF
cat > src/server.js <<'EOF'
'use strict'

const http = require('node:http')
const unpipe = require('./unpipe')

const MAX_BODY_BYTES = 1024 * 1024

function createServer () {
  return http.createServer((req, res) => {
    if (req.method === 'GET' && req.url === '/health') {
      res.writeHead(200, { 'content-type': 'application/json' })
      res.end(JSON.stringify({ status: 'ok' }))
      return
    }

    if (req.method === 'POST' && req.url === '/echo') {
      echo(req, res)
      return
    }

    res.writeHead(404, { 'content-type': 'application/json' })
    res.end(JSON.stringify({ error: 'not found' }))
  })
}

// Streams the request body back. If it grows too large, detach the request
// from every destination before responding, then drain the rest so the
// connection can be reused.
function echo (req, res) {
  let received = 0

  req.on('data', (chunk) => {
    received += chunk.length
    if (received > MAX_BODY_BYTES && !res.headersSent) {
      unpipe(req)
      req.resume()
      res.writeHead(413, { 'content-type': 'application/json', connection: 'close' })
      res.end(JSON.stringify({ error: 'payload too large' }))
    }
  })

  res.writeHead(200, { 'content-type': req.headers['content-type'] || 'application/octet-stream' })
  req.pipe(res)
}

module.exports = { createServer }

if (require.main === module) {
  const port = Number(process.env.PORT) || 3000
  createServer().listen(port, () => {
    console.log(`listening on http://localhost:${port}`)
  })
}
EOF
